sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    //

    var qtrackid = current.qtrack_id;
    if (current.state == 'Processed') {
        var elog = new GlideRecord('x_hsb11_hsbcmss_eh_hsbc_email_log');
        elog.addQuery('qtrack_id', qtrackid);
        elog.query();
        if (elog.next()) {
            elog.api_response_from_qtrack = 'Sent Successfully';
            elog.update();
        }
    }
    if (current.state == 'Error') {
        // Calls the rest message configured to send widget failture details to ITID instance and creates an Event

        var failureDescription = "HSBC MSS iQube Widget failure, details of the error are as below - ServiceNow Reference -" + current.servicenow_task_id.number + " Timestamp : " + current.response_date + "Error code - " + current.error_code + "Error Body - " + current.error_body;
        var createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('WARNING', failureDescription, 'MSSiQubeSNWidget_QTRACK');
    }
})(current, previous);
